-- ============================================================================
-- V254: Keep Envers revision numbering on the revinfo identity column.
--
-- V120 created revinfo.rev as GENERATED BY DEFAULT AS IDENTITY, but Envers'
-- DefaultRevisionEntity expected a pooled sequence "revinfo_seq" (allocation
-- 50) that no migration created, so every audited write on a fresh database
-- failed. The application now maps its own revision entity
-- (com.posgateway.aml.entity.audit.AuditRevisionEntity) onto the identity
-- column, so no sequence is needed.
--
-- Some databases were patched by hand with "CREATE SEQUENCE revinfo_seq" and
-- then received explicitly-numbered revisions that the identity generator
-- never saw. Move the identity's next value past max(rev) so new revisions
-- cannot collide with those rows. The hand-made sequence (if any) is left in
-- place: nothing uses it any more and dropping objects we did not create is
-- riskier than leaving them.
-- ============================================================================
SELECT setval(pg_get_serial_sequence('revinfo', 'rev'),
              GREATEST((SELECT COALESCE(MAX(rev), 0) FROM revinfo), 1),
              (SELECT COUNT(*) > 0 FROM revinfo));
